/**
 * no-catch-as-control-flow — flag a catch clause that swallows the error AND
 * fabricates a return value (returns a call/constructor result). That shape is
 * try/catch used as an if: the error is not handled, it is silently traded for
 * an alternate code path. Wrap only the throwing call in a status-returning
 * probe (`catch { return null; }` — a sentinel fallback is fine), or observe
 * the error (log/rethrow/map it) before returning a response.
 *
 * Detect-only: the fix (a probe function, an error log) needs human judgment.
 *
 * A catch *swallows* when it has no parameter or never references it. A catch
 * *fabricates* when a return statement in its own scope (not a nested
 * function) returns a call, constructor, or awaited-call result — literals,
 * identifiers and object literals are sentinel fallbacks and stay legal.
 */
const FUNCTION_TYPES = new Set([
    "FunctionDeclaration",
    "FunctionExpression",
    "ArrowFunctionExpression",
]);
const FABRICATING_TYPES = new Set(["CallExpression", "NewExpression"]);
function isAstNode(value) {
    return Boolean(value) && typeof value.type === "string";
}
function childNodes(node) {
    return Object.keys(node)
        .filter((key) => key !== "parent")
        .flatMap((key) => {
        const value = node[key];
        return Array.isArray(value) ? value : [value];
    })
        .filter(isAstNode);
}
function referencesName(node, name) {
    if (!isAstNode(node))
        return false;
    if (node.type === "Identifier")
        return node.name === name;
    return childNodes(node).some((child) => referencesName(child, name));
}
/** Return statements in the catch's own scope — nested functions excluded. */
function ownReturns(node, acc = []) {
    if (!isAstNode(node))
        return acc;
    if (FUNCTION_TYPES.has(node.type))
        return acc;
    if (node.type === "ReturnStatement") {
        acc.push(node);
        return acc;
    }
    childNodes(node).forEach((child) => ownReturns(child, acc));
    return acc;
}
function fabricatesValue(returnStatement) {
    let argument = returnStatement.argument;
    if (!argument)
        return false;
    if (argument.type === "AwaitExpression")
        argument = argument.argument;
    return FABRICATING_TYPES.has(argument.type);
}
function swallowsError(catchClause) {
    if (!catchClause.param)
        return true;
    if (catchClause.param.type !== "Identifier")
        return false;
    return !referencesName(catchClause.body, catchClause.param.name);
}
export default {
    meta: {
        type: "problem",
        docs: {
            description: "disallow catch clauses that swallow the error and fabricate a return value (try/catch as control flow)",
        },
        schema: [],
        messages: {
            catchAsControlFlow: "This catch swallows the error and fabricates a return value — try/catch as control flow. Wrap only the throwing call in a status-returning probe, or observe the error before mapping it.",
        },
    },
    create(context) {
        return {
            CatchClause(node) {
                if (!swallowsError(node))
                    return;
                if (!ownReturns(node.body).some(fabricatesValue))
                    return;
                context.report({ node, messageId: "catchAsControlFlow" });
            },
        };
    },
};
=== declare-near-use.mjs ===
/**
 * declare-near-use — declare variables close to their usage. A `const` bound
 * at the top of a block and first read a dozen statements later makes the
 * reader carry it the whole way down; declaring it right above its first use
 * keeps the value and its purpose on the same screen.
 *
 * What counts: a `const` / `let` declaration that is a direct child of a
 * `BlockStatement` or `Program`, whose first reference (init reference
 * excluded) lands in a sibling statement of the same list. When more than
 * `maxDistance` (default 5) statements separate the declaration from that
 * sibling, the declaration is reported. Skipped, because a later position
 * would change meaning or is not obviously better:
 *   - the first reference sits inside a nested block or function (a loop body,
 *     a callback, an `if` arm) — hoisting it into the branch is a judgment call;
 *   - references spread over two or more branching siblings (`if` / `switch` /
 *     `try`) — the declaration is shared state between arms;
 *   - `let` without an initialiser — deliberately declared for later assignment;
 *   - `var`, and exported Program-level declarations (an export is a reference).
 *
 * Detect-only: moving a declaration past side-effecting statements needs a
 * human to confirm nothing observes the old order.
 */
const BLOCK_PARENTS = new Set(["BlockStatement", "Program"]);
const BRANCHING = new Set(["IfStatement", "SwitchStatement", "TryStatement"]);
const NESTING = new Set([
    "BlockStatement",
    "FunctionDeclaration",
    "FunctionExpression",
    "ArrowFunctionExpression",
    "ClassBody",
    "StaticBlock",
]);
function isCandidate(node) {
    if (node.kind === "var" || !BLOCK_PARENTS.has(node.parent.type)) {
        return false;
    }
    return node.declarations.every((declarator) => declarator.init);
}
/**
 * Walks from a reference up to the statement list holding `declaration`,
 * noting whether a nested scope sits between the reference and that sibling.
 */
function locateReference(identifier, declaration) {
    const list = declaration.parent;
    let node = identifier;
    let nested = false;
    while (node.parent && node.parent !== list) {
        node = node.parent;
        nested = nested || NESTING.has(node.type);
    }
    return { statement: node, nested, name: identifier.name };
}
function usageSites(sourceCode, declaration) {
    return sourceCode
        .getDeclaredVariables(declaration)
        .flatMap((variable) => variable.references)
        .filter((reference) => !reference.init)
        .map((reference) => reference.identifier)
        .sort((a, b) => a.range[0] - b.range[0])
        .map((identifier) => locateReference(identifier, declaration))
        .filter((site) => site.statement !== declaration);
}
function spansBranches(sites) {
    const arms = new Set(sites
        .map((site) => site.statement)
        .filter((statement) => BRANCHING.has(statement.type)));
    return arms.size >= 2;
}
function statementDistance(declaration, statement) {
    const list = declaration.parent.body;
    return list.indexOf(statement) - list.indexOf(declaration) - 1;
}
export default {
    meta: {
        type: "suggestion",
        docs: {
            description: "Require a const/let declaration to sit within a few statements of its first use in the same block",
        },
        schema: [
            {
                type: "object",
                properties: { maxDistance: { type: "integer", minimum: 0 } },
                additionalProperties: false,
            },
        ],
        messages: {
            declaredTooEarly: "'{{name}}' is declared {{distance}} statements before its first use (max {{maxDistance}}); move it down",
        },
    },
    create(context) {
        const maxDistance = context.options[0]?.maxDistance ?? 5;
        const { sourceCode } = context;
        return {
            VariableDeclaration(node) {
                if (!isCandidate(node)) {
                    return;
                }
                const sites = usageSites(sourceCode, node);
                const [first] = sites;
                if (!first || first.nested || spansBranches(sites)) {
                    return;
                }
                const distance = statementDistance(node, first.statement);
                if (distance > maxDistance) {
                    context.report({
                        node,
                        messageId: "declaredTooEarly",
                        data: { name: first.name, distance, maxDistance },
                    });
                }
            },
        };
    },
};
=== callee-below-caller.mjs ===
/**
 * callee-below-caller — place functions in the downward direction: a reader
 * meets the caller first and finds the callee below it. A file then reads like
 * a newspaper — headline at the top, detail as you scroll — instead of forcing
 * the reader to hold a pile of helpers in their head before the point arrives.
 *
 * What counts: only top-level `FunctionDeclaration`s (direct `Program` children,
 * including `export function`). For each, the FIRST reference in source order
 * that lives inside another top-level function names its caller; a callee whose
 * declaration sits ABOVE that caller is reported. Exemptions:
 *   - a callee referenced at module level (exports, top-level statements,
 *     class bodies) is an entry point, not a helper, and is never reported;
 *   - mutual recursion (A calls B and B calls A) has no downward order;
 *   - a callee with several callers is judged against its first caller only;
 *   - with `exportedFirst` (default true) exported functions are never
 *     reported — they are the entry points and belong at the top.
 *
 * Detect-only: moving a declaration is a cut-and-paste a human should own.
 */
function declaredFunction(statement) {
    const declaration = statement.type === "ExportNamedDeclaration" ||
        statement.type === "ExportDefaultDeclaration"
        ? statement.declaration
        : statement;
    if (!declaration || declaration.type !== "FunctionDeclaration") {
        return null;
    }
    if (!declaration.id) {
        return null;
    }
    return { node: declaration, exported: declaration !== statement };
}
function topLevelFunctions(program) {
    const found = new Map();
    for (const statement of program.body) {
        const entry = declaredFunction(statement);
        if (entry) {
            found.set(entry.node.id.name, entry);
        }
    }
    return found;
}
function enclosingTopLevelFunction(identifier, program) {
    let node = identifier;
    while (node.parent && node.parent !== program) {
        node = node.parent;
    }
    const entry = declaredFunction(node);
    return entry ? entry.node.id.name : null;
}
function nameVariable(sourceCode, fn) {
    return sourceCode
        .getDeclaredVariables(fn)
        .find((variable) => variable.name === fn.id.name);
}
/**
 * Every reference to `callee` mapped to the top-level function holding it,
 * sorted by source position. A `null` caller marks a module-level reference.
 */
function callersOf(sourceCode, callee, program) {
    const variable = nameVariable(sourceCode, callee);
    const references = variable ? variable.references : [];
    return references
        .map((reference) => reference.identifier)
        .sort((a, b) => a.range[0] - b.range[0])
        .map((identifier) => enclosingTopLevelFunction(identifier, program))
        .filter((caller) => caller !== callee.id.name);
}
function firstCaller(callers) {
    if (callers.length === 0 || callers.includes(null)) {
        return null;
    }
    return callers[0];
}
function isMutualRecursion(callersByName, callee, caller) {
    return callersByName.get(caller).includes(callee);
}
function reportIfAbove(context, functions, callersByName, callee) {
    const caller = firstCaller(callersByName.get(callee));
    if (!caller || isMutualRecursion(callersByName, callee, caller)) {
        return;
    }
    const calleeNode = functions.get(callee).node;
    const callerNode = functions.get(caller).node;
    if (calleeNode.range[0] < callerNode.range[0]) {
        context.report({
            node: calleeNode.id,
            messageId: "calleeAboveCaller",
            data: { callee, caller },
        });
    }
}
export default {
    meta: {
        type: "suggestion",
        docs: {
            description: "Require a top-level function to be declared below the function that first calls it (callers above callees)",
        },
        schema: [
            {
                type: "object",
                properties: { exportedFirst: { type: "boolean" } },
                additionalProperties: false,
            },
        ],
        messages: {
            calleeAboveCaller: "'{{callee}}' is declared above its caller '{{caller}}'; move it below",
        },
    },
    create(context) {
        const exportedFirst = context.options[0]?.exportedFirst ?? true;
        const { sourceCode } = context;
        return {
            "Program:exit"(program) {
                const functions = topLevelFunctions(program);
                const callersByName = new Map([...functions].map(([name, entry]) => [
                    name,
                    callersOf(sourceCode, entry.node, program),
                ]));
                const judged = [...functions]
                    .filter(([, entry]) => !(exportedFirst && entry.exported))
                    .map(([name]) => name);
                for (const callee of judged) {
                    reportIfAbove(context, functions, callersByName, callee);
                }
            },
        };
    },
};
=== require-colocated-tests.mjs ===
/**
 * require-colocated-tests — every test must live next to the source it covers,
 * never inside a `__tests__/` directory. ESLint can't move files, so this is
 * report-only; the fix is to relocate the file beside its source.
 */
export default {
    meta: {
        type: "problem",
        docs: {
            description: "tests must be colocated with their source, not in __tests__/",
        },
        schema: [],
        messages: {
            colocate: "Test files must be colocated next to their source, not in a __tests__/ directory.",
        },
    },
    create(context) {
        const inTestsDir = context.filename.split(/[/\\]/).includes("__tests__");
        if (!inTestsDir)
            return {};
        return {
            Program(node) {
                context.report({
                    node,
                    loc: { line: 1, column: 0 },
                    messageId: "colocate",
                });
            },
        };
    },
};
=== test-imports-its-subject.mjs ===
/**
 * test-imports-its-subject — a `*.test.ts` file must load the real thing it
 * tests: a first-party module, or (for a suite whose subject is an artifact
 * rather than code) the file itself, read from disk. Never a copy.
 *
 * Written after `memory-lifecycle.test.ts` was found importing only vitest and
 * then defining its own copy of the function it claimed to test, under the
 * comment "(copied from memory-lifecycle.ts)". Eleven scoring tests and three
 * parsing tests were green against re-implementations, with fourteen spec
 * anchors reporting those statements covered. A change to production code could
 * not have failed any of them.
 *
 * A `[validated by]` link proves a test EXISTS. This is the cheapest available
 * proof that the test also RUNS the thing.
 *
 * Deliberately not checked: whether the imported binding is actually called. A
 * test can legitimately import a type-adjacent helper and exercise the subject
 * indirectly, and chasing that needs type information this rule does not have.
 * The bar here is "the real subject is loaded", which is exactly the bar the
 * copy failed.
 *
 * First-party means a relative path, or a package under one of the npm scopes
 * named in `firstPartyScopes` (default `[]`, e.g. `["@re-cinq"]` for a
 * monorepo whose workspace packages a suite may reach through a barrel).
 */
/** Suites that drive a system rather than one module, so no subject is implied. */
const EXEMPT_SUFFIXES = [
    ".integration.test",
    ".acceptance.test",
    ".e2e.test",
    ".contract.test",
];
/** The same exemption spelled as a directory, which is how lore-api spells it. */
const EXEMPT_DIRS = ["integration-tests"];
/** Accepts a scope with or without its trailing slash: `@org` and `@org/`. */
function isUnderScope(source, scopes) {
    return scopes.some((scope) => {
        const prefix = scope.endsWith("/") ? scope : `${scope}/`;
        return source.startsWith(prefix);
    });
}
/** `/a/b/scoring.test.ts` → `scoring`; null when this is not a test file. */
function subjectOf(filename) {
    const segments = filename.split(/[/\\]/);
    const base = segments.pop() ?? "";
    const match = base.match(/^(.*)\.test\.(ts|tsx|mts|cts|js|jsx|mjs|cjs)$/);
    if (!match) {
        return null;
    }
    if (segments.some((segment) => EXEMPT_DIRS.includes(segment))) {
        return null;
    }
    const stem = match[1];
    return EXEMPT_SUFFIXES.some((s) => `${stem}.test`.endsWith(s)) ? null : stem;
}
/**
 * Does `source` load the real subject?
 *
 * Deliberately NOT "does it match the filename". A first cut required the test
 * to import the module it is named after and flagged 86 files, nearly all
 * legitimate: `agent-events-oversized.test.ts` tests a facet of
 * `agent-events.ts`, and a suite may reach its subject through a barrel or a
 * sibling. The property worth enforcing is the one the copy violated — that the
 * test loads SOME production module rather than re-implementing its subject.
 *
 * `node:fs` counts, because a suite that reads a repo file asserts on the very
 * artifact it names: a migration's SQL, a stylesheet's tokens, the PR template,
 * package.json, the source tree itself. Its subject is a file rather than a
 * module, so there is no module for it to import, and it is copying nothing —
